  `placca_f` varchar(25) DEFAULT NULL COMMENT \'Presenza di placca di tipo F (da definire)\',
  `placca_c` varchar(25) DEFAULT NULL COMMENT \'Presenza di placca di tipo C (da definire)\',
  `placca_fc` varchar(25) DEFAULT NULL COMMENT \'Presenza di placca di tipo FC (da definire)\',
  `STENOsi` tinyint(1) DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) presenza di stenosi\',
  `F23` varchar(25) DEFAULT NULL COMMENT \'Campo F23, significato da definire\',
