  `bmi_tsa` varchar(25) DEFAULT NULL COMMENT \'Indice di Massa Corporea (BMI) al momento della TSA\',
  `CVD_risk` varchar(25) DEFAULT NULL COMMENT \'Rischio cardiovascolare calcolato (es. % a 10 anni)\',
  `Framingham_score` varchar(25) DEFAULT NULL COMMENT \'Punteggio di rischio cardiovascolare secondo score di Framingham\',
  `DAD_score` varchar(25) DEFAULT NULL COMMENT \'Punteggio di rischio cardiovascolare secondo score D:A:D\',
