                'Trattamentovecchio' => '`Trattamentovecchio` varchar(200) DEFAULT NULL COMMENT \'Nome della terapia ARV precedente\' AFTER `Trattamentonuovodal`',
                'trattamentocausaabbandono_id' => '`trattamentocausaabbandono_id` varchar(30) DEFAULT NULL COMMENT \'ID della causa di interruzione della terapia precedente (Foreign Key)\' AFTER `Trattamentovecchio`',
