                'PAS' => '`PAS` float DEFAULT NULL COMMENT \'Pressione Arteriosa Sistolica (massima) in mmHg\' AFTER `circonferenza`',
                'Creatinina' => '`Creatinina` float DEFAULT NULL COMMENT \'Valore della creatinina nel siero (mg/dL)\' AFTER `PAS`',
                'HIVRNA' => '`HIVRNA` tinyint DEFAULT NULL COMMENT \'Valore della carica virale (HIV-RNA) in copie/mL\' AFTER `Creatinina`',
                'HIVRNAnorilevabile' => '`HIVRNAnorilevabile` tinyint(1) DEFAULT \'0\' COMMENT \'Flag (1=Sì, 0=No) che indica se la carica virale è non rilevabile\' AFTER `HIVRNA`',
                'placcasxbordi' => '`placcasxbordi` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: bordi (Flag 1/0)\' AFTER `HIVRNAnorilevabile`',
                'placcadxbordi' => '`placcadxbordi` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: bordi (Flag 1/0)\' AFTER `placcasxbordi`',
                'placcasxclivaggio' => '`placcasxclivaggio` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: clivaggio (Flag 1/0)\' AFTER `placcadxbordi`',
                'placcadxclivaggio' => '`placcadxclivaggio` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: clivaggio (Flag 1/0)\' AFTER `placcasxclivaggio`',
                'placcasxomogenea' => '`placcasxomogenea` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: omogenea (Flag 1/0)\' AFTER `placcadxclivaggio`',
                'placcadxomogenea' => '`placcadxomogenea` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: omogenea (Flag 1/0)\' AFTER `placcasxomogenea`',
                'placcasxombra' => '`placcasxombra` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: ombra (Flag 1/0)\' AFTER `placcadxomogenea`',
                'placcdsxombra' => '`placcdsxombra` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: ombra (Flag 1/0) - NOME CAMPO CON POSSIBILE REFUSO (placcdsxombra)\' AFTER `placcasxombra`',
                'menopausa' => '`menopausa` tinyint(1) DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) che indica lo stato di menopausa\' AFTER `placcdsxombra`',
                'PAD' => '`PAD` float DEFAULT NULL COMMENT \'Pressione Arteriosa Diastolica (minima) in mmHg\' AFTER `menopausa`',
