  `visitadel` date DEFAULT NULL COMMENT \'Data in cui è stata effettuata la visita\',
  `CD4` float DEFAULT NULL COMMENT \'Valore assoluto dei linfociti CD4 (cellule/mm³)\',
  `CD4CD8` float DEFAULT NULL COMMENT \'Rapporto tra linfociti CD4 e CD8\',
  `Trattamentonuovo` varchar(200) DEFAULT NULL COMMENT \'Nome della nuova terapia antiretrovirale (ARV) iniziata\',
  `Trattamentonuovodal` date DEFAULT NULL COMMENT \'Data di inizio della nuova terapia ARV\',
  `Trattamentovecchio` varchar(200) DEFAULT NULL COMMENT \'Nome della terapia ARV precedente\',
  `trattamentocausaabbandono_id` varchar(30) DEFAULT NULL COMMENT \'ID della causa di interruzione della terapia precedente (Foreign Key)\',
  `peso` float DEFAULT NULL COMMENT \'Peso del paziente in kg\',
  `circonferenza` float DEFAULT NULL COMMENT \'Circonferenza vita in cm\',
  `PAS` float DEFAULT NULL COMMENT \'Pressione Arteriosa Sistolica (massima) in mmHg\',
  `Creatinina` float DEFAULT NULL COMMENT \'Valore della creatinina nel siero (mg/dL)\',
  `HIVRNA` tinyint DEFAULT NULL COMMENT \'Valore della carica virale (HIV-RNA) in copie/mL\',
  `HIVRNAnorilevabile` tinyint(1) DEFAULT \'0\' COMMENT \'Flag (1=Sì, 0=No) che indica se la carica virale è non rilevabile\',
  `placcasxbordi` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: bordi (Flag 1/0)\',
  `placcadxbordi` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: bordi (Flag 1/0)\',
  `placcasxclivaggio` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: clivaggio (Flag 1/0)\',
  `placcadxclivaggio` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: clivaggio (Flag 1/0)\',
  `placcasxomogenea` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: omogenea (Flag 1/0)\',
  `placcadxomogenea` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: omogenea (Flag 1/0)\',
  `placcasxombra` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea sinistra: ombra (Flag 1/0)\',
  `placcdsxombra` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: ombra (Flag 1/0) - NOME CAMPO CON POSSIBILE REFUSO (placcdsxombra)\',
  `menopausa` tinyint(1) DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) che indica lo stato di menopausa\',
  `PAD` float DEFAULT NULL COMMENT \'Pressione Arteriosa Diastolica (minima) in mmHg\',
  `Colesterolo` float DEFAULT NULL COMMENT \'Valore del colesterolo totale (mg/dL)\',
  `HDL` float DEFAULT NULL COMMENT \'Valore del colesterolo HDL (mg/dL)\',
  `LDL` float DEFAULT NULL COMMENT \'Valore del colesterolo LDL (mg/dL)\',
  `Trigliceridi` float DEFAULT NULL COMMENT \'Valore dei trigliceridi (mg/dL)\',
  `Glicemia` float DEFAULT NULL COMMENT \'Valore della glicemia a digiuno (mg/dL)\',
  `Insulina` float DEFAULT NULL COMMENT \'Valore dell\'\'insulina (µU/mL)\',
  `GPT` float DEFAULT NULL COMMENT \'Transaminasi GPT/ALT (U/L)\',
  `GOT` float DEFAULT NULL COMMENT \'Transaminasi GOT/AST (U/L)\',
  `gamma_GT` float DEFAULT NULL COMMENT \'Valore della Gamma GT (U/L)\',
  `ProteurinaFlag` tinyint(1) DEFAULT \'0\' COMMENT \'Flag (1=Sì, 0=No) che indica la presenza di proteinuria\',
  `Proteinuria` float DEFAULT NULL COMMENT \'Valore quantitativo della proteinuria (es. mg/24h)\',
  `centro` varchar(80) DEFAULT NULL COMMENT \'Nome del centro medico di riferimento\',
