                'placcdsxombra' => '`placcdsxombra` tinyint(1) DEFAULT NULL COMMENT \'Caratteristica della placca carotidea destra: ombra (Flag 1/0) - NOME CAMPO CON POSSIBILE REFUSO (placcdsxombra)\' AFTER `placcasxombra`',
