  `annonascita` date DEFAULT NULL COMMENT \'Anno di nascita del paziente\',
  `iniziali` varchar(3) DEFAULT NULL COMMENT \'Iniziali del nome e cognome del paziente\',
  `centro` varchar(80) DEFAULT NULL COMMENT \'Nome del centro medico di riferimento\',
  `centrocode` varchar(3) DEFAULT NULL COMMENT \'Codice identificativo del centro medico\',
  `pazientecode` varchar(15) DEFAULT NULL COMMENT \'Codice anonimizzato del paziente\',
  `datanascita` date DEFAULT NULL COMMENT \'Data di nascita completa del paziente\',
  `sesso` varchar(1) DEFAULT \'M\' COMMENT \'Sesso del paziente (M/F)\',
  `menopausa` tinyint(1) DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) che indica lo stato di menopausa\',
  `etnia_id` varchar(30) DEFAULT \'caucasico\' COMMENT \'ID dell\'\'etnia di appartenenza (Foreign Key)\',
  `rischio_id` varchar(30) DEFAULT NULL COMMENT \'ID del fattore di rischio per la trasmissione di HIV (Foreign Key)\',
  `studioanni` tinyint DEFAULT NULL COMMENT \'Anni di scolarizzazione completati\',
  `statocivile_id` varchar(30) DEFAULT NULL COMMENT \'ID dello stato civile (Foreign Key)\',
  `fumo_id` char(10) DEFAULT NULL COMMENT \'ID dello stato di fumatore (es. fumatore, ex, mai) (Foreign Key)\',
  `fumodurata` tinyint DEFAULT NULL COMMENT \'Durata del fumo in anni\',
  `lavoro_id` varchar(30) DEFAULT NULL COMMENT \'ID della condizione lavorativa/professione (Foreign Key)\',
  `cammino` tinyint DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) per attività fisica: camminare regolarmente\',
  `sport` tinyint DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) per attività fisica: pratica sportiva regolare\',
  `ictus_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per ictus (Foreign Key)\',
  `cardiopatie_id` char(30) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per cardiopatie (Foreign Key)\',
  `diabete_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per diabete (Foreign Key)\',
