  `NNRTI_TSA` tinyint(1) DEFAULT NULL COMMENT \'Flag terapia con classe NNRTI al momento del primo/principale esame TSA\',
  `PI_TSA` tinyint(1) DEFAULT NULL COMMENT \'Flag terapia con classe Inibitori della Proteasi (PI) al momento del primo/principale esame TSA\',
