  `STATIN_EVER` tinyint(1) DEFAULT NULL COMMENT \'Flag paziente ha mai assunto statine\',
  `FIBRATO_ON` tinyint(1) DEFAULT NULL COMMENT \'Flag paziente in terapia con fibrati al momento del primo/principale esame TSA\',
  `FIBRATO_EVER` tinyint(1) DEFAULT NULL COMMENT \'Flag paziente ha mai assunto fibrati\',
  `IPER_ON` tinyint(1) DEFAULT NULL COMMENT \'Flag paziente in terapia anti-ipertensiva al momento del primo/principale esame TSA\',
  `IPER_EVER` tinyint(1) DEFAULT NULL COMMENT \'Flag paziente ha mai assunto terapia anti-ipertensiva\',
  `FUMO` varchar(25) DEFAULT NULL COMMENT \'Stato di fumatore al momento del primo/principale esame TSA\',
  `PESO_TSA` varchar(25) DEFAULT NULL COMMENT \'Peso in kg al momento del primo/principale esame TSA\',
  `PD_TSA` varchar(25) DEFAULT NULL COMMENT \'Pressione diastolica al momento del primo/principale esame TSA\',
  `PS_TSA` varchar(25) DEFAULT NULL COMMENT \'Pressione sistolica al momento del primo/principale esame TSA\',
