  `placca_sx` varchar(25) DEFAULT NULL COMMENT \'Presenza placca a sinistra al momento del primo/principale esame TSA\',
  `placca_bil` varchar(25) DEFAULT NULL COMMENT \'Presenza placca bilaterale al momento del primo/principale esame TSA\',
  `placca_f` varchar(25) DEFAULT NULL COMMENT \'Presenza placca tipo F al momento del primo/principale esame TSA\',
  `placca_c` varchar(25) DEFAULT NULL COMMENT \'Presenza placca tipo C al momento del primo/principale esame TSA\',
  `placca_fc` varchar(25) DEFAULT NULL COMMENT \'Presenza placca tipo FC al momento del primo/principale esame TSA\',
  `STENOsi` tinyint(1) DEFAULT NULL COMMENT \'Flag presenza stenosi al momento del primo/principale esame TSA\',
  `F23` varchar(25) DEFAULT NULL COMMENT \'Campo F23, significato da definire\',
  `F24` varchar(25) DEFAULT NULL COMMENT \'Campo F24, significato da definire\',
  `bmi_tsa` varchar(25) DEFAULT NULL COMMENT \'Indice di Massa Corporea (BMI) al momento del primo/principale esame TSA\',
  `CVD_risk` varchar(25) DEFAULT NULL COMMENT \'Rischio cardiovascolare calcolato al momento del primo/principale esame TSA\',
  `Framingham_score` varchar(25) DEFAULT NULL COMMENT \'Punteggio Framingham al momento del primo/principale esame TSA\',
  `DAD_score` varchar(25) DEFAULT NULL COMMENT \'Punteggio D:A:D al momento del primo/principale esame TSA\',
