  `CARDIO1` varchar(25) DEFAULT NULL COMMENT \'Descrizione primo evento cardiovascolare\',
  `D_CARDIO2` varchar(25) DEFAULT NULL COMMENT \'Data secondo evento cardiovascolare\',
  `CARDIO2` varchar(25) DEFAULT NULL COMMENT \'Descrizione secondo evento cardiovascolare\',
