  KEY `ipertensionefar_id` (`ipertensionefar_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2595 DEFAULT CHARSET=utf8mb3 COMMENT=\'Tabella anagrafica contenente i dati demografici, anamnestici e di background di ogni paziente arruolato.\'',
            'columns' => [
                'id' => '`id` bigint NOT NULL AUTO_INCREMENT COMMENT \'ID univoco autoincrementale del paziente (Primary Key)\' FIRST',
                'arruolato' => '`arruolato` date DEFAULT NULL COMMENT \'Data di arruolamento del paziente nello studio/coorte\' AFTER `id`',
