                'iniziali' => '`iniziali` varchar(3) DEFAULT NULL COMMENT \'Iniziali del nome e cognome del paziente\' AFTER `annonascita`',
                'centro' => '`centro` varchar(80) DEFAULT NULL COMMENT \'Nome del centro medico di riferimento\' AFTER `iniziali`',
                'centrocode' => '`centrocode` varchar(3) DEFAULT NULL COMMENT \'Codice identificativo del centro medico\' AFTER `centro`',
