                'datanascita' => '`datanascita` date DEFAULT NULL COMMENT \'Data di nascita completa del paziente\' AFTER `pazientecode`',
                'sesso' => '`sesso` varchar(1) DEFAULT \'M\' COMMENT \'Sesso del paziente (M/F)\' AFTER `datanascita`',
                'menopausa' => '`menopausa` tinyint(1) DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) che indica lo stato di menopausa\' AFTER `sesso`',
                'etnia_id' => '`etnia_id` varchar(30) DEFAULT \'caucasico\' COMMENT \'ID dell\'\'etnia di appartenenza (Foreign Key)\' AFTER `menopausa`',
                'rischio_id' => '`rischio_id` varchar(30) DEFAULT NULL COMMENT \'ID del fattore di rischio per la trasmissione di HIV (Foreign Key)\' AFTER `etnia_id`',
                'studioanni' => '`studioanni` tinyint DEFAULT NULL COMMENT \'Anni di scolarizzazione completati\' AFTER `rischio_id`',
                'statocivile_id' => '`statocivile_id` varchar(30) DEFAULT NULL COMMENT \'ID dello stato civile (Foreign Key)\' AFTER `studioanni`',
                'fumo_id' => '`fumo_id` char(10) DEFAULT NULL COMMENT \'ID dello stato di fumatore (es. fumatore, ex, mai) (Foreign Key)\' AFTER `statocivile_id`',
                'fumodurata' => '`fumodurata` tinyint DEFAULT NULL COMMENT \'Durata del fumo in anni\' AFTER `fumo_id`',
                'lavoro_id' => '`lavoro_id` varchar(30) DEFAULT NULL COMMENT \'ID della condizione lavorativa/professione (Foreign Key)\' AFTER `fumodurata`',
