                'sport' => '`sport` tinyint DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) per attività fisica: pratica sportiva regolare\' AFTER `cammino`',
                'ictus_id' => '`ictus_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per ictus (Foreign Key)\' AFTER `sport`',
                'cardiopatie_id' => '`cardiopatie_id` char(30) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per cardiopatie (Foreign Key)\' AFTER `ictus_id`',
                'diabete_id' => '`diabete_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per diabete (Foreign Key)\' AFTER `cardiopatie_id`',
                'dislipidemie_id' => '`dislipidemie_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per dislipidemie (Foreign Key)\' AFTER `diabete_id`',
                'lipodistrofia_id' => '`lipodistrofia_id` char(35) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per lipodistrofia (Foreign Key)\' AFTER `dislipidemie_id`',
                'neoplasie_id' => '`neoplasie_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per neoplasie (Foreign Key)\' AFTER `lipodistrofia_id`',
                'osteoporosi_id' => '`osteoporosi_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per osteoporosi (Foreign Key)\' AFTER `neoplasie_id`',
                'insuffrenale_id' => '`insuffrenale_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per insufficienza renale (Foreign Key)\' AFTER `osteoporosi_id`',
                'ormonali_id' => '`ormonali_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per patologie ormonali (Foreign Key)\' AFTER `insuffrenale_id`',
