                'epatite_id' => '`epatite_id` char(20) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per epatite virale (B, C, etc.) (Foreign Key)\' AFTER `cirrosi_id`',
                'infezionehiv_id' => '`infezionehiv_id` char(10) DEFAULT NULL COMMENT \'ID della modalità di trasmissione dell\'\'infezione da HIV (Foreign Key)\' AFTER `epatite_id`',
                'stadiocdc' => '`stadiocdc` char(10) DEFAULT NULL COMMENT \'Stadio clinico dell\'\'infezione da HIV secondo classificazione CDC (A, B, C)\' AFTER `infezionehiv_id`',
                'datahiv' => '`datahiv` date DEFAULT \'2000-01-01\' COMMENT \'Data della prima diagnosi di positività per HIV\' AFTER `stadiocdc`',
