                'naive_id' => '`naive_id` char(10) DEFAULT NULL COMMENT \'Flag/ID che indica se il paziente non ha mai ricevuto terapia antiretrovirale (naïve) (Foreign Key)\' AFTER `positivodal`',
                'pi_id' => '`pi_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per uso pregresso di Inibitori della Proteasi (PI) (Foreign Key)\' AFTER `naive_id`',
                'nrti_id' => '`nrti_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per uso pregresso di Inibitori Nucleosidici della Trascrittasi Inversa (NRTI) (Foreign Key)\' AFTER `pi_id`',
                'nnrti_id' => '`nnrti_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per uso pregresso di Inibitori Non-Nucleosidici della Trascrittasi Inversa (NNRTI) (Foreign Key)\' AFTER `nrti_id`',
                'ini_id' => '`ini_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per uso pregresso di Inibitori dell\'\'Integrasi (INI/II) (Foreign Key)\' AFTER `nnrti_id`',
                'artaltro_id' => '`artaltro_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per uso pregresso di altre classi di antiretrovirali (Foreign Key)\' AFTER `ini_id`',
                'artterapie_id' => '`artterapie_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per numero di linee terapeutiche effettuate (Foreign Key)\' AFTER `artaltro_id`',
                'trattamentodal' => '`trattamentodal` date DEFAULT NULL COMMENT \'Data di inizio della prima terapia antiretrovirale\' AFTER `artterapie_id`',
                'farmaciterapia' => '`farmaciterapia` text COMMENT \'Descrizione della terapia antiretrovirale attuale\' AFTER `trattamentodal`',
                'ultimaterapia' => '`ultimaterapia` text COMMENT \'Descrizione dell\'\'ultima terapia antiretrovirale effettuata\' AFTER `farmaciterapia`',
                'haart' => '`haart` tinyint DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) che indica se il paziente è in terapia HAART\' AFTER `ultimaterapia`',
                'infezioni_id' => '`infezioni_id` char(10) DEFAULT NULL COMMENT \'Flag/ID per anamnesi positiva per infezioni opportunistiche (Foreign Key)\' AFTER `haart`',
