                'cd4data' => '`cd4data` date DEFAULT NULL COMMENT \'Data dell\'\'ultimo valore CD4 disponibile\' AFTER `cd4nadir`',
                'altezza' => '`altezza` smallint unsigned DEFAULT NULL COMMENT \'Altezza del paziente in cm\' AFTER `cd4data`',
