                'active' => '`active` tinyint(1) DEFAULT \'1\' COMMENT \'Flag di stato del record (1=Attivo, 0=Eliminato logicamente)\' AFTER `commenti`',
                'created' => '`created` datetime DEFAULT NULL COMMENT \'Timestamp di creazione del record\' AFTER `active`',
                'modified' => '`modified` datetime DEFAULT NULL COMMENT \'Timestamp dell\'\'ultima modifica del record\' AFTER `created`',
