                'INIZIO_ARV' => '`INIZIO_ARV` varchar(25) DEFAULT NULL COMMENT \'Data di inizio della prima terapia ARV (dato duplicato)\' AFTER `FDR`',
                'D_AIDS' => '`D_AIDS` varchar(25) DEFAULT NULL COMMENT \'Data della diagnosi di AIDS\' AFTER `INIZIO_ARV`',
                'D_DIABETE' => '`D_DIABETE` varchar(25) DEFAULT NULL COMMENT \'Data della diagnosi di diabete\' AFTER `D_AIDS`',
                'D_DECESSO' => '`D_DECESSO` varchar(25) DEFAULT NULL COMMENT \'Data del decesso\' AFTER `D_DIABETE`',
