                'NADIR_CD4_TSA' => '`NADIR_CD4_TSA` varchar(25) DEFAULT NULL COMMENT \'Valore nadir di CD4 registrato (dato duplicato)\' AFTER `YEARS_ARV_TSA`',
                'HCV_TSA' => '`HCV_TSA` tinyint(1) DEFAULT NULL COMMENT \'Flag (1=Sì, 0=No) di co-infezione con HCV al momento del primo/principale esame TSA\' AFTER `NADIR_CD4_TSA`',
                'HBV_TSA' => '`HBV_TSA` varchar(25) DEFAULT NULL COMMENT \'Stato infezione HBV al momento del primo/principale esame TSA\' AFTER `HCV_TSA`',
                'D_STATUS' => '`D_STATUS` varchar(25) DEFAULT NULL COMMENT \'Stato del paziente (es. vivo/deceduto)\' AFTER `HBV_TSA`',
                'TIME_SOP_TSA' => '`TIME_SOP_TSA` varchar(25) DEFAULT NULL COMMENT \'Tempo di sopravvivenza al momento del primo/principale esame TSA\' AFTER `D_STATUS`',
